<?php $route=$members?'members':'voters'; ?>
<div class="page-heading"><div><span class="section-kicker">MY JURISDICTION</span><h1><?= $members?'Members':'Voters' ?></h1><p>Only records permitted by your current executive appointments appear here.</p></div></div><section class="card"><div class="card-body"><form action="<?= e(base_url('index.php')) ?>" method="get" class="d-flex gap-2"><input type="hidden" name="page" value="<?= e($route) ?>"><input class="form-control" type="search" name="q" maxlength="100" value="<?= e($q) ?>" placeholder="Search name, voter ID or Party ID" aria-label="Search permitted records"><button class="btn btn-primary">Search</button><a class="btn btn-light" href="<?= e(url($route)) ?>">Reset</a></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Voter ID</th><th>Gender</th><th>Party ID / Sys No.</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['full_name']) ?></td><td><?= e($row['voter_id']) ?></td><td><?= e(label($row['gender'])) ?></td><td><?= e($row['membership_id']?member_identifier($row):'Not a member') ?></td><td><a href="<?= e(url('voter',['id'=>$row['id']])) ?>">View record</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">No permitted records match.</td></tr><?php endif; ?></tbody></table></div><div class="card-body d-flex justify-content-between"><span><?= number($total) ?> records · Page <?= $p ?> of <?= $last ?></span><div><?php if($p>1): ?><a class="btn btn-sm btn-light" href="<?= e(url($route,['q'=>$q,'p'=>$p-1])) ?>">Previous</a><?php endif; ?> <?php if($p<$last): ?><a class="btn btn-sm btn-light" href="<?= e(url($route,['q'=>$q,'p'=>$p+1])) ?>">Next</a><?php endif; ?></div></div></section>
